values
  (1007, 'rooster', 'Rooster', 'Gallus gallus domesticus', 'Common', 'Farms, villages, and urban homes across Vietnam', 'An adult male domestic chicken recognized by its comb and long tail feathers.', null, '/creatures/bird.svg', true, 50, '["Roosters use distinct calls to warn a flock and announce territory."]'::jsonb, null, false, 'https://en.wikipedia.org/wiki/Rooster', 7, true, 'A bold flock leader that balances pressure and defense.', 'Domestic worldwide, including Vietnam', 'Balanced', null, 'WildQuest original'),
