  (1012, 'african_grey_parrot', 'African Grey Parrot', 'Psittacus erithacus', 'Uncommon', 'Homes and licensed aviaries', 'A highly intelligent companion parrot with grey feathers and a red tail.', null, '/creatures/parrot.svg', true, 50, '["African grey parrots are known for learning and reproducing complex sounds."]'::jsonb, null, false, 'https://en.wikipedia.org/wiki/Grey_parrot', 87, true, 'A clever aerial scout that wins through speed and timing.', 'Central Africa; kept as a companion bird in Vietnam', 'Scout', null, 'WildQuest original'),
